const scheduledChecks = `-- name: ScheduledChecks :many
SELECT s.id, s.table_id, s.due FROM prep.scheduled_checks s WHERE s.campaign_id = $1 ORDER BY s.created_at, s.id
`

type ScheduledChecksRow struct {
	ID      uuid.UUID
	TableID uuid.UUID
	Due     string
}

func (q *Queries) ScheduledChecks(ctx context.Context, campaignID uuid.UUID) ([]ScheduledChecksRow, error) {
	rows, err := q.db.Query(ctx, scheduledChecks, campaignID)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	items := []ScheduledChecksRow{}
	for rows.Next() {
		var i ScheduledChecksRow
		if err := rows.Scan(&i.ID, &i.TableID, &i.Due); err != nil {
			return nil, err
		}
		items = append(items, i)
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}

